fn handle_tile_map_pointer(
    ui: &egui::Ui,
    response: &egui::Response,
    loaded: &mut LoadedTileMap,
    layer: &engine_authoring::TileLayerId,
    pointer_cell: Option<engine_authoring::TileCell>,
    tool: TileTool2d,
    visible_bounds: engine_authoring::TileRect,
    work_budget: usize,
) -> Result<(), String> {
    if ui.input(|input| input.key_pressed(egui::Key::Escape)) && loaded.gesture_active {
        loaded.cancel_gesture()?;
        return Ok(());
    }

    let primary = egui::PointerButton::Primary;
    let drag_stopped = response.drag_stopped_by(primary);
    let selected_tile = loaded.selected_tile.clone();

    match tool {
        TileTool2d::Paint | TileTool2d::Erase => {
            if response.drag_started_by(primary) {
                loaded
                    .service
                    .begin_gesture()
                    .map_err(|error| error.to_string())?;
                loaded.gesture_active = true;
                loaded.gesture_start = pointer_cell;
                if let Some(cell) = pointer_cell {
                    let tile = matches!(tool, TileTool2d::Paint)
                        .then(|| selected_tile.clone())
                        .flatten();
                    loaded
                        .service
                        .paint(layer, cell, tile)
                        .map_err(|error| error.to_string())?;
                }
            }

            if loaded.gesture_active && response.dragged_by(primary) {
                if let Some(cell) = pointer_cell {
                    let tile = matches!(tool, TileTool2d::Paint)
                        .then(|| selected_tile.clone())
                        .flatten();
                    loaded
                        .service
                        .paint(layer, cell, tile)
                        .map_err(|error| error.to_string())?;
                }
            }

            if loaded.gesture_active && drag_stopped {
                loaded.commit_gesture()?;
            } else if response.clicked_by(primary) && !drag_stopped && !loaded.gesture_active {
                loaded
                    .service
                    .begin_gesture()
                    .map_err(|error| error.to_string())?;
                loaded.gesture_active = true;
                loaded.gesture_start = pointer_cell;
                if let Some(cell) = pointer_cell {
                    let tile = matches!(tool, TileTool2d::Paint)
                        .then(|| selected_tile.clone())
                        .flatten();
                    loaded
                        .service
                        .paint(layer, cell, tile)
                        .map_err(|error| error.to_string())?;
                }
                loaded.commit_gesture()?;
            }
        }
        TileTool2d::Rectangle | TileTool2d::Line => {
            if response.drag_started_by(primary) {
                loaded
                    .service
                    .begin_gesture()
                    .map_err(|error| error.to_string())?;
                loaded.gesture_active = true;
                loaded.gesture_start = pointer_cell;
            }

            if loaded.gesture_active && drag_stopped {
                let start = loaded.gesture_start;
                match (start, pointer_cell) {
                    (Some(start), Some(end)) => {
                        let operation = if matches!(tool, TileTool2d::Rectangle) {
                            loaded.service.rectangle(
                                layer,
                                engine_authoring::TileRect::from_corners(start, end),
                                selected_tile.clone(),
                                work_budget,
                            )
                        } else {
                            loaded.service.line(
                                layer,
                                start,
                                end,
                                selected_tile.clone(),
                                work_budget,
                            )
                        };
                        if let Err(error) = operation {
                            loaded.cancel_gesture()?;
                            return Err(error.to_string());
                        }
                        loaded.commit_gesture()?;
                    }
                    _ => loaded.cancel_gesture()?,
                }
            } else if response.clicked_by(primary) && !drag_stopped && !loaded.gesture_active {
                let Some(cell) = pointer_cell else {
                    return Ok(());
                };
                loaded
                    .service
                    .begin_gesture()
                    .map_err(|error| error.to_string())?;
                loaded.gesture_active = true;
                loaded.gesture_start = Some(cell);
                let result = if matches!(tool, TileTool2d::Rectangle) {
                    loaded.service.rectangle(
                        layer,
                        engine_authoring::TileRect::from_corners(cell, cell),
                        selected_tile,
                        work_budget,
                    )
                } else {
                    loaded
                        .service
                        .line(layer, cell, cell, selected_tile, work_budget)
                };
                if let Err(error) = result {
                    loaded.cancel_gesture()?;
                    return Err(error.to_string());
                }
                loaded.commit_gesture()?;
            }
        }
        TileTool2d::Fill => {
            if response.clicked_by(primary) {
                let Some(cell) = pointer_cell else {
                    return Ok(());
                };
                loaded
                    .service
                    .begin_gesture()
                    .map_err(|error| error.to_string())?;
                loaded.gesture_active = true;
                loaded.gesture_start = Some(cell);
                if let Err(error) = loaded.service.fill_bounded(
                    layer,
                    cell,
                    visible_bounds,
                    selected_tile,
                    work_budget,
                ) {
                    loaded.cancel_gesture()?;
                    return Err(error.to_string());
                }
                loaded.commit_gesture()?;
            }
        }
        TileTool2d::Eyedropper => {
            if response.clicked_by(primary) {
                let Some(cell) = pointer_cell else {
                    return Ok(());
                };
                loaded.selected_tile = loaded.service.eyedropper(layer, cell);
            }
        }
        TileTool2d::SelectStamp => {
            if loaded.stamp.cells.is_empty() {
                if response.drag_started_by(primary) {
                    loaded.gesture_start = pointer_cell;
                }
                if drag_stopped {
                    if let (Some(start), Some(end)) = (loaded.gesture_start.take(), pointer_cell) {
                        loaded.stamp = loaded.service.copy_stamp(
                            layer,
                            engine_authoring::TileRect::from_corners(start, end),
                        );
                    }
                } else if response.clicked_by(primary) {
                    if let Some(cell) = pointer_cell {
                        loaded.stamp = loaded.service.copy_stamp(
                            layer,
                            engine_authoring::TileRect::from_corners(cell, cell),
                        );
                    }
                }
            } else if response.clicked_by(primary) {
                let Some(origin) = pointer_cell else {
                    return Ok(());
                };
                let stamp = loaded.stamp.clone();
                loaded
                    .service
                    .begin_gesture()
                    .map_err(|error| error.to_string())?;
                loaded.gesture_active = true;
                loaded.gesture_start = Some(origin);
                if let Err(error) =
                    loaded.service.paste_stamp(layer, origin, &stamp, work_budget)
                {
                    loaded.cancel_gesture()?;
                    return Err(error.to_string());
                }
                loaded.commit_gesture()?;
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tile_map_pointer_tests {
    use super::TileTool2d;

    #[test]
    fn tile_tools_keep_all_first_release_gestures_reachable() {
        let tools = [
            TileTool2d::Paint,
            TileTool2d::Erase,
            TileTool2d::Rectangle,
            TileTool2d::Line,
            TileTool2d::Fill,
            TileTool2d::Eyedropper,
            TileTool2d::SelectStamp,
        ];
        assert_eq!(tools.len(), 7);
        assert_eq!(TileTool2d::SelectStamp.label(), "Select/Stamp");
    }
}
